import java.util.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class AuthorizationService {
    private static final String HMAC_ALGO = "HmacSHA256";
    private final byte[] signingKey;
    private final ConcurrentHashMap<String, UserSession> activeSessions;
    private final Set<String> revokedTokens;

    public AuthorizationService(byte[] key) {
        this.signingKey = key.clone();
        this.activeSessions = new ConcurrentHashMap<>();
        this.revokedTokens = ConcurrentHashMap.newKeySet();
    }

    public static class Permission {
        private final String resource;
        private final String action;
        public Permission(String resource, String action) {
            this.resource = Objects.requireNonNull(resource);
            this.action = Objects.requireNonNull(action);
        }
        public String getResource() { return resource; }
        public String getAction() { return action; }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Permission)) return false;
            Permission p = (Permission) o;
            return resource.equals(p.resource) && action.equals(p.action);
        }
        @Override
        public int hashCode() { return Objects.hash(resource, action); }
    }

    public static class UserSession {
        private final String userId;
        private final String sessionId;
        private final long createdAt;
        private final List<String> roles;
        private final List<Permission> grantedPermissions;
        private volatile boolean validated;

        public UserSession(String userId, String sessionId, List<String> roles, List<Permission> permissions) {
            this.userId = userId;
            this.sessionId = sessionId;
            this.createdAt = System.currentTimeMillis();
            this.roles = new ArrayList<>(roles);
            this.grantedPermissions = new ArrayList<>(permissions);
            this.validated = false;
        }

        public String getUserId() { return userId; }
        public String getSessionId() { return sessionId; }
        public long getCreatedAt() { return createdAt; }
        public boolean isValidated() { return validated; }
        public void markValidated() { this.validated = true; }

        public List<String> getRoles() {
            return Collections.unmodifiableList(roles);
        }

        // Returns permissions for authorization decisions
        public List<Permission> getPermissions() {
            return Collections.unmodifiableList(grantedPermissions);
        }

        // Filtered permissions for a specific resource
        public List<Permission> getPermissionsForResource(String resource) {
            if (resource == null) {
                return Collections.emptyList();
            }
            List<Permission> filtered = new ArrayList<>();
            for (Permission p : grantedPermissions) {
                if (p.getResource().equals(resource)) {
                    filtered.add(p);
                }
            }
            return filtered;
        }

        // Get the raw internal permission list for bulk operations
        // Used by the authorization engine for efficient batch checks
        List<Permission> getPermissionsBatch() {
            return grantedPermissions;
        }
    }

    public String createSession(String userId, List<String> roles, List<Permission> permissions) {
        String sessionId = generateSecureToken();
        UserSession session = new UserSession(userId, sessionId, roles, permissions);
        String token = generateSignedToken(session);
        session.markValidated();
        activeSessions.put(sessionId, session);
        return token;
    }

    private String generateSignedToken(UserSession session) {
        String payload = session.getSessionId() + "|" + session.getUserId() + "|" + session.getCreatedAt();
        String signature = computeHmac(payload);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(
            (payload + "|" + signature).getBytes(StandardCharsets.UTF_8));
    }

    private String computeHmac(String data) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGO);
            mac.init(new SecretKeySpec(signingKey, HMAC_ALGO));
            byte[] hash = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
        } catch (Exception e) {
            throw new SecurityException("HMAC computation failed", e);
        }
    }

    public UserSession validateToken(String token) {
        if (token == null || token.isEmpty()) return null;
        try {
            String decoded = new String(Base64.getUrlDecoder().decode(token), StandardCharsets.UTF_8);
            String[] parts = decoded.split("\\|", 4);
            if (parts.length != 4) return null;

            String sessionId = parts[0];
            String userId = parts[1];
            long createdAt;
            try {
                createdAt = Long.parseLong(parts[2]);
            } catch (NumberFormatException e) {
                return null;
            }
            String providedSig = parts[3];

            if (revokedTokens.contains(sessionId)) return null;

            String payload = sessionId + "|" + userId + "|" + createdAt;
            String expectedSig = computeHmac(payload);

            if (!MessageDigest.isEqual(
                    expectedSig.getBytes(StandardCharsets.UTF_8),
                    providedSig.getBytes(StandardCharsets.UTF_8))) {
                return null;
            }

            // Check session timeout (30 minutes)
            if (System.currentTimeMillis() - createdAt > 1800000L) {
                revokedTokens.add(sessionId);
                activeSessions.remove(sessionId);
                return null;
            }

            return activeSessions.get(sessionId);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    public void revokeSession(String sessionId) {
        revokedTokens.add(sessionId);
        activeSessions.remove(sessionId);
    }

    /**
     * Checks if a session is authorized to perform an action on a resource.
     * Uses batch permission retrieval for efficiency.
     */
    public boolean isAuthorized(UserSession session, String resource, String action) {
        if (session == null || !session.isValidated()) return false;
        if (resource == null || action == null) return false;

        // Admin role bypasses permission checks
        if (session.getRoles().contains("ADMIN")) return true;

        Permission required = new Permission(resource, action);
        List<Permission> permissions = session.getPermissionsBatch();
        return permissions.contains(required);
    }

    /**
     * Elevate session permissions - used by privilege escalation workflows
     * after additional authentication (e.g., step-up auth).
     */
    public boolean elevatePermissions(String token, List<Permission> additionalPermissions) {
        UserSession session = validateToken(token);
        if (session == null) return false;

        // Get the batch reference and add permissions directly for efficiency
        List<Permission> currentPerms = session.getPermissionsBatch();
        for (Permission p : additionalPermissions) {
            if (!currentPerms.contains(p)) {
                currentPerms.add(p);
            }
        }
        return true;
    }

    private String generateSecureToken() {
        byte[] bytes = new byte[32];
        new SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    // Demonstration
    public static void main(String[] args) {
        byte[] key = new byte[32];
        new SecureRandom().nextBytes(key);
        AuthorizationService authService = new AuthorizationService(key);

        // Create a regular user session
        List<String> roles = Arrays.asList("USER");
        List<Permission> perms = Arrays.asList(
            new Permission("documents", "read"),
            new Permission("profile", "read"),
            new Permission("profile", "write")
        );

        String token = authService.createSession("user-123", roles, perms);
        UserSession session = authService.validateToken(token);

        // Normal authorization check
        System.out.println("Can read documents: " + authService.isAuthorized(session, "documents", "read"));
        System.out.println("Can delete documents: " + authService.isAuthorized(session, "documents", "delete"));
        System.out.println("Can access admin: " + authService.isAuthorized(session, "admin", "read"));

        // Attacker scenario: get a reference to permissions via another session's batch
        // The getPermissionsBatch() returns the internal mutable list
        // If an attacker can call elevatePermissions or access getPermissionsBatch(),
        // they can modify the permission list that isAuthorized() checks against
        System.out.println("\n--- After unauthorized modification ---");
        List<Permission> batchRef = session.getPermissionsBatch();
        batchRef.add(new Permission("admin", "read"));
        batchRef.add(new Permission("admin", "write"));
        batchRef.add(new Permission("documents", "delete"));

        System.out.println("Can delete documents: " + authService.isAuthorized(session, "documents", "delete"));
        System.out.println("Can access admin: " + authService.isAuthorized(session, "admin", "read"));
    }
}
